CREATE TABLE attendance_work_batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), period_id uuid NOT NULL REFERENCES payroll_periods(id), actor text NOT NULL, revision integer NOT NULL DEFAULT 1, state text NOT NULL DEFAULT 'Draft', acknowledged_digest text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attendance_work_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES attendance_work_batches(id), period_id uuid NOT NULL REFERENCES payroll_periods(id), employee_id uuid NOT NULL REFERENCES employees(id), draft jsonb NOT NULL, state text NOT NULL DEFAULT 'Draft', source_request jsonb, source_result jsonb, impacted_period_ids jsonb NOT NULL DEFAULT '[]', evidence_version text NOT NULL, owner_id text NOT NULL, result text, attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX attendance_work_delivery ON attendance_work_plans(state,updated_at);
CREATE TABLE attendance_work_treatments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES attendance_work_plans(id), period_id uuid NOT NULL REFERENCES payroll_periods(id), employee_id uuid NOT NULL REFERENCES employees(id), day date NOT NULL, version text NOT NULL, payload jsonb NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX attendance_work_treatment_day ON attendance_work_treatments(period_id,employee_id,day);
CREATE TABLE attendance_work_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid REFERENCES attendance_work_plans(id), actor text NOT NULL, action text NOT NULL, details jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attendance_adjustment_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES attendance_work_plans(id), period_id uuid NOT NULL REFERENCES payroll_periods(id), employee_id uuid NOT NULL REFERENCES employees(id), state text NOT NULL DEFAULT 'Open', before_evidence jsonb NOT NULL, after_evidence jsonb, impact jsonb, adjustment_reference text, conclusion text, closed_by text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(plan_id,period_id,employee_id));
CREATE TABLE attendance_work_raw_logs (plan_id uuid NOT NULL REFERENCES attendance_work_plans(id), change_id text NOT NULL, raw_log_id integer NOT NULL REFERENCES attendance_raw_logs(id), PRIMARY KEY(plan_id,change_id));
CREATE TABLE attendance_work_exclusions (raw_log_id integer PRIMARY KEY REFERENCES attendance_raw_logs(id), plan_id uuid NOT NULL REFERENCES attendance_work_plans(id), reason text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE attendance_work_source_exclusions (period_id uuid NOT NULL REFERENCES payroll_periods(id), event_id uuid NOT NULL, plan_id uuid NOT NULL REFERENCES attendance_work_plans(id), reason text NOT NULL, version text NOT NULL, active boolean NOT NULL DEFAULT true, PRIMARY KEY(period_id,event_id));
